function unwrap(o) {
  if (o === null || o === undefined) return '';
  if (typeof o === 'string') {
    var s = o.trim();
    if (s.charAt(0) === '{' && s.charAt(s.length - 1) === '}') {
      try {
        var parsed = JSON.parse(s);
        return unwrap(parsed);
      } catch (e) {
        if (s.charAt(0) === '"' && s.charAt(s.length - 1) === '"') return s.substring(1, s.length - 1);
        return s;
      }
    }
    if (s.charAt(0) === '"' && s.charAt(s.length - 1) === '"') return s.substring(1, s.length - 1);
    return s;
  }
  if (typeof o === 'object') {
    var keys = Object.keys(o);
    if (keys.length === 1) return unwrap(o[keys[0]]);
    try { return JSON.stringify(o); } catch (e) { return ''; }
  }
  return String(o);
}

var source = ($json && typeof $json === 'object' && $json.text !== undefined) ? $json.text : $json;
var cleaned = unwrap(source);
return { json: { text: cleaned } };

const items = $input.all();
const results = [];

for (const item of items) {
  const itemData = { ...item.json };
  const binary = item.binary || {};

  if (binary.image) {
    const imageData = binary.image;
    const mimeType = imageData.mimeType || 'image/jpeg';
    const data = imageData.data;
    itemData.imageBase64 = 'data:' + mimeType + ';base64,' + data;
    itemData.hasImage = true;
  } else {
    itemData.hasImage = false;
    itemData.imageBase64 = '';
  }

  results.push({ json: itemData });
}

return results;
